    ld8(k + offa, ak);
    ld8(wq + head * D + c, wqv);
    ld8(wk + head * D + c, wkv);
    const uint64_t pol = pol_evict_last();

    for (;;) {
        // A holds row r; prefetch row r+nhw into B
        int rb = r + nhw;
        const size_t offb = (size_t)rb * D + c;
        const bool mb = rb < n_rows;
        if (mb) { ld8(q + offb, bq); ld8(k + offb, bk); }
        process_pair(aq, ak, wqv, wkv, qo, ko, offa, eps, pol);
        if (!mb) break;
        // B holds row rb; prefetch rb+nhw into A
        r = rb + nhw;
        offa = (size_t)r * D + c;
        const bool ma = r < n_rows;
        if (ma) { ld8(q + offa, aq); ld8(k + offa, ak); }
        process_pair(bq, bk, wqv, wkv, qo, ko, offb, eps, pol);
        if (!ma) break;
