// ---------------- parent: one-shot, 16 rows per CTA ----------------
__global__ void __launch_bounds__(THREADS, 8)
qk_rms_kernel(const float* __restrict__ q, const float* __restrict__ k,
              const float* __restrict__ wq, const float* __restrict__ wk,
              float* __restrict__ qo, float* __restrict__ ko, int n_tiles, float eps) {
    const int bid = blockIdx.x;
    const bool is_k = bid >= n_tiles;
    const int tile = is_k ? bid - n_tiles : bid;
    const float* __restrict__ x = is_k ? k : q;
    const float* __restrict__ w = is_k ? wk : wq;
    float* __restrict__ y = is_k ? ko : qo;

    const int r = threadIdx.x >> 4;
    const int c = (threadIdx.x & 15) * 8;
    const size_t row = (size_t)tile * ROWS + r;
    const int head = (tile % GROUPS) * ROWS + r;

    float xv[8], wv[8], yv[8];
    ld8(x + row * D + c, xv);
    ld8(w + (size_t)head * D + c, wv);
    const uint64_t pol_out = pol_evict_last();

    float s = 0.0f;
#pragma unroll
    for (int i = 0; i < 8; ++i) s = fmaf(xv[i], xv[i], s);
    s += __shfl_xor_sync(0xffffffffu, s, 8);
    s += __shfl_xor_sync(0xffffffffu, s, 4);
    s += __shfl_xor_sync(0xffffffffu, s, 2);
    s += __shfl_xor_sync(0xffffffffu, s, 1);
    const float inv = rsqrtf(s * (1.0f / (float)D) + eps);
#pragma unroll
    for (int i = 0; i < 8; ++i) yv[i] = (xv[i] * inv) * wv[i];
    st8_h(y + row * D + c, yv, pol_out);
}

__device__ __forceinline__ void process_row(const float (&x)[8], const float (&w)[8],
                                            float* __restrict__ y, float eps, uint64_t pol) {
    float s = 0.0f;
#pragma unroll
    for (int i = 0; i < 8; ++i) s = fmaf(x[i], x[i], s);
    s += __shfl_xor_sync(0xffffffffu, s, 8);
    s += __shfl_xor_sync(0xffffffffu, s, 4);
    s += __shfl_xor_sync(0xffffffffu, s, 2);
    s += __shfl_xor_sync(0xffffffffu, s, 1);
    const float inv = rsqrtf(s * (1.0f / (float)D) + eps);
    float yv[8];
#pragma unroll
    for (int i = 0; i < 8; ++i) yv[i] = (x[i] * inv) * w[i];
    st8_h(y, yv, pol);
}

// ---------------- capped persistent over the concatenated [Q;K] rows ----------------
// Global row g in [0, 2n): g < n -> Q row g, else K row g-n. nhw = gridDim.x*16 is a multiple of 48
// and n is a multiple of 48, so head = hw % 48 is fixed per thread. Trip count is warp-uniform.
__global__ void __launch_bounds__(THREADS, CPS)
qk_rms_persist(const float* __restrict__ q, const float* __restrict__ k,
               const float* __restrict__ wq, const float* __restrict__ wk,
               float* __restrict__ qo, float* __restrict__ ko, int n_rows, int nhw, float eps) {
    const int hw = blockIdx.x * (THREADS / 16) + (threadIdx.x >> 4);
    const int c = (threadIdx.x & 15) * 8;
    const int total = 2 * n_rows;
    int g = hw;
    if (g >= total) return;
    const int hoff = (hw % H) * D + c;

    float ax[8], aw[8], bx[8], bw[8];
    bool ak = g >= n_rows;
    size_t offa = (size_t)(ak ? g - n_rows : g) * D + c;
    ld8((ak ? k : q) + offa, ax);
    ld8((ak ? wk : wq) + hoff, aw);
    const uint64_t pol = pol_evict_last();

    for (;;) {
        const int gb = g + nhw;
        const bool mb = gb < total;
        const bool bk = gb >= n_rows;
        const size_t offb = (size_t)(bk ? gb - n_rows : gb) * D + c;
        if (mb) { ld8((bk ? k : q) + offb, bx); ld8((bk ? wk : wq) + hoff, bw); }
        process_row(ax, aw, (ak ? ko : qo) + offa, eps, pol);
        if (!mb) break;
        g = gb + nhw;
        const bool ma = g < total;
        ak = g >= n_rows;
        offa = (size_t)(ak ? g - n_rows : g) * D + c;
        if (ma) { ld8((ak ? k : q) + offa, ax); ld8((ak ? wk : wq) + hoff, aw); }
        process_row(bx, bw, (bk ? ko : qo) + offb, eps, pol);
        if (!ma) break;
    }
}

