// Tile t of the concatenated [Q;K] rows: rows t*16 .. t*16+15 (never straddles Q/K: n % 48 == 0).
__device__ __forceinline__ void tile_ptrs(int t, int r, int c, int n_tiles,
                                          const float* __restrict__ q, const float* __restrict__ k,
                                          const float* __restrict__ wq, const float* __restrict__ wk,
                                          float* __restrict__ qo, float* __restrict__ ko,
                                          const float*& xp, const float*& wp, float*& yp) {
    const bool is_k = t >= n_tiles;
    const int tt = is_k ? t - n_tiles : t;
    const size_t off = ((size_t)tt * ROWS + r) * D + c;
    const int head = (tt % GROUPS) * ROWS + r;
    xp = (is_k ? k : q) + off;
    wp = (is_k ? wk : wq) + head * D + c;
    yp = (is_k ? ko : qo) + off;
}

// ---------------- capped persistent, contiguous balanced tile ranges ----------------
__global__ void __launch_bounds__(THREADS, CPS)
qk_rms_persist(const float* __restrict__ q, const float* __restrict__ k,
               const float* __restrict__ wq, const float* __restrict__ wk,
               float* __restrict__ qo, float* __restrict__ ko, int n_tiles, int base, int rem, float eps) {
    const int b = blockIdx.x;
    const int t0 = b * base + min(b, rem);
    const int t_end = t0 + base + (b < rem ? 1 : 0);    // CTA-uniform
    const int r = threadIdx.x >> 4;
    const int c = (threadIdx.x & 15) * 8;
    const uint64_t pol = pol_evict_last();

    float ax[8], aw[8], bx[8], bw[8];
    const float *xa, *wa, *xb, *wb;
    float *ya, *yb;
    int t = t0;
    tile_ptrs(t, r, c, n_tiles, q, k, wq, wk, qo, ko, xa, wa, ya);
    ld8(xa, ax); ld8(wa, aw);
    for (;;) {
        const bool mb = t + 1 < t_end;
        if (mb) {
            tile_ptrs(t + 1, r, c, n_tiles, q, k, wq, wk, qo, ko, xb, wb, yb);
            ld8(xb, bx); ld8(wb, bw);
        }
        process_row(ax, aw, ya, eps, pol);
        if (!mb) break;
        t += 2;
        const bool ma = t < t_end;
        if (ma) {
            tile_ptrs(t, r, c, n_tiles, q, k, wq, wk, qo, ko, xa, wa, ya);
            ld8(xa, ax); ld8(wa, aw);
        }
        process_row(bx, bw, yb, eps, pol);
        if (!ma) break;
    }
}

int num_sms() {
    static int sms = -1;
    if (sms < 0) {
        int dev = 0;
        cudaGetDevice(&dev);
        cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, dev);
    }
    return sms;
}

